import itertools

def get_all_2x2_squares(grid, n):
    squares = []
    for i in range(n - 1):
        for j in range(n - 1):
            squares.append((i, j))
    return squares

def apply_rule1(grid, square, n):
    i, j = square
    cells = [(i, j), (i+1, j), (i, j+1), (i+1, j+1)]
    infected = [grid[r][c] for r, c in cells]
    if sum(infected) == 3:
        new_grid = [row[:] for row in grid]
        for r, c in cells:
            if new_grid[r][c] == 0:
                new_grid[r][c] = 1
        return new_grid
    return None

def apply_rule2(grid, square, n):
    i, j = square
    cells = [(i, j), (i+1, j), (i, j+1), (i+1, j+1)]
    infected = [grid[r][c] for r, c in cells]
    if sum(infected) == 2:
        new_grid = [row[:] for row in grid]
        for r, c in cells:
            new_grid[r][c] = 1 - new_grid[r][c]
        return new_grid
    return None

def can_reach_full(grid, n):
    import collections
    start_state = tuple(tuple(row) for row in grid)
    visited = {start_state}
    queue = collections.deque([start_state])

    while queue:
        curr = queue.popleft()
        if all(all(cell == 1 for cell in row) for row in curr):
            return True

        curr_grid = [list(row) for row in curr]
        for sq in get_all_2x2_squares(curr_grid, n):
            # Try Rule 1
            res1 = apply_rule1(curr_grid, sq, n)
            if res1:
                state1 = tuple(tuple(row) for row in res1)
                if state1 not in visited:
                    visited.add(state1)
                    queue.append(state1)
            # Try Rule 2
            res2 = apply_rule2(curr_grid, sq, n)
            if res2:
                state2 = tuple(tuple(row) for row in res2)
                if state2 not in visited:
                    visited.add(state2)
                    queue.append(state2)
    return False

def solve_for_n(n):
    import itertools
    all_cells = list(itertools.product(range(n), range(n)))
    for k in range(n*n + 1):
        possible_for_all = True
        for initial_infected in itertools.combinations(all_cells, k):
            grid = [[0]*n for _ in range(n)]
            for r, c in initial_infected:
                grid[r][c] = 1
            if not can_reach_full(grid, n):
                possible_for_all = False
                break
        if possible_for_all:
            return k
    return n*n

