import random

def get_all_2x2_squares(n):
    squares = []
    for i in range(n - 1):
        for j in range(n - 1):
            squares.append((i, j))
    return squares

def can_reach_full_fast(grid_tuple, n, squares):
    visited = {grid_tuple}
    queue = collections.deque([grid_tuple])

    while queue:
        curr = queue.popleft()
        if all(all(cell == 1 for cell in row) for row in curr):
            return True

        # To make it faster, we use a list of lists for manipulation
        curr_grid = [list(row) for row in curr]
        for sq in squares:
            i, j = sq
            # Rule 1: sum == 3
            s = curr_grid[i][j] + curr_grid[i+1][j] + curr_grid[i][j+1] + curr_grid[i+1][j+1]
            if s == 3:
                new_grid = [row[:] for row in curr_grid]
                # Find the 0 and make it 1
                for r, c in [(i,j), (i+1,j), (i,j+1), (i+1,j+1)]:
                    if new_grid[r][c] == 0:
                        new_grid[r][c] = 1
                        break
                state = tuple(tuple(row) for row in new_grid)
                if state not in visited:
                    visited.add(state)
                    queue.append(state)
            # Rule 2: sum == 2
            if s == 2:
                new_grid = [row[:] for row in curr_grid]
                for r, c in [(i,j), (i+1,j), (i,j+1), (i+1,j+1)]:
                    new_grid[r][c] = 1 - new_grid[r][c]
                state = tuple(tuple(row) for row in new_grid)
                if state not in visited:
                    visited.add(state)
                    queue.append(state)
    return False

